code.css:
.hg-step{display:flex;gap:var(--s4);align-items:flex-start;padding:var(--s4) 0;border-bottom:1px solid var(--line)}
.hg-step:first-child{padding-top:0}
.hg-num{flex:0 0 26px;height:26px;border-radius:50%;background:var(--ink);color:var(--on-ink);
  display:grid;place-items:center;font:500 13px/1 var(--font-sans);margin-top:2px}
.hg-step label{flex:1}
.hg-grow{flex:1;min-width:0}
.hg-hint{margin:6px 0 0;font-size:var(--t-14);color:var(--muted);line-height:1.45}
.hg-v{font-family:var(--font-mono);font-weight:400;color:var(--muted);margin-left:6px}
.hg-groups{margin-top:var(--s5)}
.hg-groups:empty{display:none}
.hg-g{border-top:1px solid var(--line);padding:var(--s4) 0}
.hg-g h4{margin:0 0 4px;font:500 var(--t-16)/1.3 var(--font-sans)}
.hg-g p{margin:0 0 var(--s3);font-size:var(--t-14);color:var(--muted)}
.hg-tags{display:flex;flex-wrap:wrap;gap:6px}
.hg-tag{font-family:var(--font-mono);font-size:var(--t-14);padding:5px 9px;
  border:1px solid var(--line-strong);border-radius:var(--r-sm);background:var(--surface-2);
  cursor:pointer;position:relative}
.hg-tag::before{content:"";position:absolute;left:0;right:0;top:50%;height:44px;transform:translateY(-50%)}
.hg-tag.off{opacity:.4;text-decoration:line-through}
.hg-g .btn{margin-top:var(--s3);height:38px;padding:0 12px;font-size:var(--t-14)}
.hg-count{float:right;font-family:var(--font-mono);font-size:var(--t-12);color:var(--muted)}
#out{min-height:3em}

