lay"],"niche":["speedrunning","cozygaming","backlogclearing","retrogaming","gamedevlog","couchcoop","completionist","firstplaythrough"]},"realestate":{"label":"Property and real estate","broad":["realestate","property","home","house","forsale"],"mid":["realestateagent","propertyinvestment","househunting","dreamhome","newlisting","realtorlife","homebuying","propertymarket"],"niche":["firsttimebuyer","fixerupper","rentalproperty","openhouseday","buytolet","propertyviewing","mortgagetips","homesurvey"]},"wedding":{"label":"Weddings and events","broad":["wedding","bride","love","celebration","event"],"mid":["weddingday","weddingphotography","weddinginspiration","bridetobe","weddingplanning","engaged","weddingdress","weddingdecor"],"niche":["intimatewedding","registryoffice","weddingonabudget","secondhanddress","elopementphotography","weddingtimeline","diyweddingdecor","backyardwedding"]},"handmade":{"label":"Handmade and crafts","broad":["handmade","craft","diy","crafting","makers"],"mid":["handmadewithlove","smallbusinessmade","crochet","knitting","craftroom","handmadejewelry","makersgonnamake","supportsmallbusiness"],"niche":["slowmaking","yarnstash","firstmarketstall","pottersofinstagram","embroideryart","resincraft","craftfairprep","workinprogresscraft"]}};
  var LIMITS={
    instagram:{name:'Instagram',max:30,advise:'Instagram allows 30. Most accounts do better with 8 to 15 well chosen ones than with 30 broad ones.'},
    tiktok:{name:'TikTok',max:20,advise:'TikTok has no hard cap but the caption is limited, so 3 to 6 tags is normal and more looks like spam.'},
    x:{name:'X / Twitter',max:10,advise:'One or two hashtags outperform more on X. Anything past three reads as noise.'},
    linkedin:{name:'LinkedIn',max:10,advise:'Three to five is the norm on LinkedIn, and they belong at the end of the post.'},
    youtube:{name:'YouTube',max:15,advise:'YouTube shows the first three above the title and ignores anything past 15.'},
    facebook:{name:'Facebook',max:10,advise:'Hashtags do very little on Facebook. Two or three at most.'},
    pinterest:{name:'Pinterest',max:20,advise:'Pinterest treats them as keywords. Describe the pin plainly rather than chasing trends.'}
  };

  var picked={broad:[],mid:[],niche:[]}, off={};

