  $('plat').innerHTML=Object.keys(LIMITS).map(function(k){
    return '<option value="'+k+'"'+(k==='instagram'?' selected':'')+'>'+LIMITS[k].name+'</option>';
  }).join('');

  function words(s){ return String(s).toLowerCase().match(/[a-z0-9]+/g)||[]; }
  // score every niche against the words in the topic, plus its own label
  function detect(topic){
    var w=words(topic); if(!w.length) return null;
    var best=null, bestScore=0;
    Object.keys(NICHES).forEach(function(k){
      var pool=(NICHES[k].label+' '+k+' '+NICHES[k].broad.join(' ')+' '+NICHES[k].mid.join(' ')).toLowerCase();
      var score=0;
      w.forEach(function(x){ if(x.length>2 && pool.indexOf(x)>=0) score+= x.length; });
      if(score>bestScore){ bestScore=score; best=k; }
    });
    return bestScore>=4 ? best : null;
  }
  function activeNiche(){
    var v=$('niche').value;
    if(v!=='auto') return v;
    return detect($('topic').value) || 'business';
  }
  // hashtags built from the user's own words, which is what makes the set
  // specific to their post rather than generic to the category
  function fromTopic(topic){
    var w=words(topic).filter(function(x){
      return x.length>2 && ['the','and','for','with','you','your','how','out','new','all','are'].indexOf(x)<0;
    });
    var joined=w.join('');
    var out=[];
    if(w.length) out.push(w[0]);
    if(joined && joined.length<=24) out.push(joined);
    if(w.length>1) out.push(w.slice(0,2).join(''));
    ['tips','daily','ideas','life','lover','community'].forEach(function(sfx){
      if(w.length && (w[0]+sfx).length<=22) out.push(w[0]+sfx);
    });
    return out;
  }
  function shuffleArr(a,seed){
    a=a.slice();
    for(var i=a.length-1;i>0;i--){
      seed=(seed*9301+49297)%233280;
      var j=Math.floor(seed/233280*(i+1));
      var t=a[i]; a[i]=a[j]; a[j]=t;
    }
    return a;
  }
  var seed=7;

  function build(){
    var plat=LIMITS[$('plat').value];
    var want=Math.min(+$('count').value, plat.max);
    var n=NICHES[activeNiche()];
    var mine=fromTopic($('topic').value);
    // A deliberate split. Broad tags give a short burst of reach and bury you
    // fast; niche tags reach fewer people but the right ones, and are where a
    // small account actually gets found.
    var nBroad=Math.max(1,Math.round(want*0.2));
    var nMid=Math.max(1,Math.round(want*0.4));
    var nNiche=Math.max(1,want-nBroad-nMid);
    picked={
      broad: shuffleArr(n.broad,seed).slice(0,nBroad),
      mid: shuffleArr(n.mid,seed+1).slice(0,nMid),
      niche: shuffleArr(mine.concat(n.niche),seed+2).slice(0,nNiche)
    };
    off={};
    render();
  }
  function render(){
    var plat=LIMITS[$('plat').value];
    var G=[
      ['broad','Big hashtags','Huge audiences, but your post drops out of sight within seconds. A couple is enough.'],
      ['mid','Medium hashtags','The useful middle. Enough people are watching, and your post stays visible for a while.'],
      ['niche','Small and specific','Fewer people, but the ones who care. This is where a smaller account actually gets found, and it includes tags built from your own words.']
    ];
    $('groups').innerHTML=G.map(function(g){
      var list=picked[g[0]]||[];
      return '<div class="hg-g"><span class="hg-count">'+list.filter(function(t){return !off[t]}).length+' of '+list.length+'</span>'+
