          return '<button type="button" class="hg-tag'+(off[t]?' off':'')+'" data-t="'+t+'">#'+t+'</button>';
        }).join('')+'</div>'+
        '<button type="button" class="btn" data-copy="'+g[0]+'">Copy these</button></div>';
    }).join('');
    var all=chosen();
    $('out').textContent = all.length ? all.map(function(t){return '#'+t}).join(' ') : 'Every hashtag is switched off. Tap one to bring it back.';
    var chars=$('out').textContent.length;
    $('note').textContent=all.length+' hashtag'+(all.length===1?'':'s')+', '+chars+
      ' characters. '+plat.advise+' Tap any hashtag to drop it.';
    if(window.WT) WT.resize();
  }
  function chosen(){
    return ['broad','mid','niche'].reduce(function(a,k){
      return a.concat((picked[k]||[]).filter(function(t){return !off[t]}));
    },[]);
  }
  function syncPlatform(){
    var plat=LIMITS[$('plat').value];
    $('count').max=plat.max;
    if(+$('count').value>plat.max) $('count').value=plat.max;
    $('countV').textContent=$('count').value;
    $('platadvice').textContent=plat.advise;
  }
  function syncNiche(){
    var d=detect($('topic').value);
    $('autohint').textContent = $('niche').value!=='auto'
      ? 'Using the topic you picked.'
      : (d ? 'Best match from your words: '+NICHES[d].label+'. Change it above if that is wrong.'
           : 'No clear match yet, so pick the closest one above.');
  }

  $('groups').addEventListener('click',function(e){
    var c=e.target.closest('[data-copy]');
    if(c){
      var list=(picked[c.dataset.copy]||[]).filter(function(t){return !off[t]});
      var ok=WT.copy(list.map(function(t){return '#'+t}).join(' '));
      c.textContent=ok?'Copied':'Press Ctrl+C';
      setTimeout(function(){c.textContent='Copy these'},1400);
      return;
    }
    var t=e.target.closest('[data-t]');
    if(t){ off[t.dataset.t]=!off[t.dataset.t]; render(); }
  });
  $('go').addEventListener('click',build);
  $('shuffle').addEventListener('click',function(){ seed=(seed*31+17)%9973; build(); });
  $('copyall').addEventListener('click',function(){
    var ok=WT.copy(chosen().map(function(t){return '#'+t}).join(' '));
    this.textContent=ok?'Copied':'Press Ctrl+C';
    var b=this; setTimeout(function(){b.textContent='Copy all'},1400);
  });
  $('plat').addEventListener('change',function(){ syncPlatform(); build(); });
  $('count').addEventListener('input',function(){ $('countV').textContent=this.value; build(); });
  $('niche').addEventListener('change',function(){ syncNiche(); build(); });
  $('topic').addEventListener('input',syncNiche);
  syncPlatform(); syncNiche(); build();
})();
